`,e.jsx(t.li,{"data-build-step":"1",children:"Identity: all-reduce = reduce-scatter + all-gather"}),`
`,e.jsx(t.li,{"data-build-step":"2",children:"DP: more throughput, one gradient all-reduce"}),`
